!function(e){function r(r){for(var n,a,i=r[0],p=r[1],s=r[2],c=0,y=[];c<i.length;c++)a=i[c],Object.prototype.hasOwnProperty.call(o,a)&&o[a]&&y.push(o[a][0]),o[a]=0;for(n in p)Object.prototype.hasOwnProperty.call(p,n)&&(e[n]=p[n]);for(d&&d(r);y.length;)y.shift()();return m.push.apply(m,s||[]),t()}function t(){for(var e,r=0;r<m.length;r++){for(var t,a=m[r],i=!0,p=1;p<a.length;p++)t=a[p],0!==o[t]&&(i=!1);i&&(m.splice(r--,1),e=n(n.s=a[0]))}return e}function n(r){if(a[r])return a[r].exports;var t=a[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,n),t.l=!0,t.exports}var a={},o={32:0},m=[];n.m=e,n.c=a,n.d=function(e,r,t){n.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},n.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},n.t=function(e,r){if(1&r&&(e=n(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(n.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var a in e)n.d(t,a,function(r){return e[r]}.bind(null,a));return t},n.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return n.d(r,"a",r),r},n.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},n.p="";var i=window.webpackJsonp=window.webpackJsonp||[],p=i.push.bind(i);i.push=r,i=i.slice();for(var s=0;s<i.length;s++)r(i[s]);var d=p;m.push([40,0]),t()}({40:function(e,r,t){"use strict";t.r(r);var n=t(0);Object(n.a)("de","army",t(41),t(1))},41:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"88mm“犀角”自行反坦克炮车","description":"<p>1942年，为了满足德军在东线苏联战场上反坦克的急切需求，德军将88mmPAK43型火炮安装在新型的Ⅲ/Ⅳ号坦克底盘上，改装为自行反坦克炮车，代号为“犀角”（也有译为“犀牛”，德文：nashorn）。该车属于重型自行反坦克炮车，从1942年10月到1943年5月先改装了100辆。后继续改装，到1945年3月一共改装了490多辆。这些反坦克炮车都装备了德国集团军直属的6个独立重型反坦克营。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}88mm“犀角”自行反坦克炮车三视图{{image}}imgs/de/army/de_army_tankdestroyernashorn_11.jpg{{text}}88mm“犀角”自行反坦克炮车{{image}}imgs/de/army/de_army_tankdestroyernashorn_12.jpg","description":"<h6>88mm“犀角”自行反坦克炮车<br>型号：8.8cm Pak 43/1 auf Fahrgestell Pzfpfw Ⅲ/Ⅳ（SF） （Sd Kfz 164）</h6><p>参数：长8.44m，宽：2.86m，高：2.65m，车重：24t；乘员4-5人；</p><p>最高车速：42km/h，最大行程：215km；</p><p>武器配备：1门88mm Pak43型71倍口径大炮；1挺MG34型机枪。</p><p>该型炮车发动机安置在经过加长的车体中部，战斗室在车体后部，空间也较宽松。</p>","caption":""}],"part2title":"战场上的“犀角”自行反坦克炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyernashorn_21.jpg","description":"1943年东线苏联战场，德军第519反坦克营的一辆88mm“犀角”自行反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_22.jpg","description":"1944年2月，在东线苏联战场上服役的德军一辆88mm“犀角”自行反坦克炮车，该车在土黄色的底色上涂上了白色曲线条，以作冬季作战的伪装。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_23.jpg","description":"1944年秋天，东线苏联战场，德军一辆双色伪装的88mm“犀角”自行反坦克炮车。该车在车体（战斗室外部）画有一个红心，表示这是主炮位置（这种给对手一个目标的做法也够幽默的了）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_24.jpg","description":"1942年-1943年间东线苏联战场，一辆德军88mm“犀角”自行反坦克炮车。这型炮车是当时德军对抗苏军坦克的主要装备之一，其88mm主炮可以在1000m距离击穿厚193mm，有30度倾角的装甲。但该型炮车是开放式的战斗室，防护薄弱，战斗室装甲只有10mm，仅能抵御步枪子弹的攻击，因此极易在战斗中受到攻击而损坏。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_25.jpg","description":"1943年冬季东线苏联战场，正在集结的德军88mm“犀角”自行反坦克炮车，炮车车组人员正在车外休息。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_26.jpg","description":"1943年东线苏联战场，一辆德军88mm“犀角”自行反坦克炮车车长正在观察战场情况。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_27.jpg","description":"一辆正在渡河的德军88mm“犀角”自行反坦克炮车。该型炮车本身没有潜渡装置，只能涉水渡过水位较低的小河。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_28.jpg","description":"1943年冬季，东线苏联战场，一辆隶属德军519重型反坦克营的88mm“犀角”自行反坦克炮车。该车车体前部捆绑着一些木桩作增强防护用，车体已涂上白色冬季伪装，炮口也用布封死以防异物进入炮管内。炮车旁边是德军步兵，他们一身冬装表明该部队已完成了冬季后勤补给。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_29.jpg","description":"一队正在公路上行进的德军88mm“犀角”自行反坦克炮车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_30.jpg","description":"1944年1月，东线苏联战场，一辆德军88mm“犀角”自行反坦克炮车正在作弹药补给。注意：88mm炮弹是装在密封圆形长桶中的（见靠在车体旁的2个桶状物），而运输时密封桶又会装在木箱中（见放在地上的2个木箱）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyernashorn_31.jpg","description":"一辆正隐蔽在树林中待命的德军88mm“犀角”自行反坦克炮车。","caption":""}]}')}});